def mot_de_passe_valide(mdp):
    if len(mdp) < 8:
        return False
    a_chiffre = False
    a_majuscule = False
    a_minuscule = False
    for c in mdp:
        if c.isdigit():
            a_chiffre = True
        elif c.isupper():
            a_majuscule = True
