from collections import deque

def bfs(graphe, depart):
    visites = {depart}
    file = deque([depart])
    ordre = []
    while file:
        sommet = file.popleft()
        ordre.append(sommet)
        for voisin in graphe[sommet]:
            if voisin not in visites:
                visites.add(voisin)
                file.append(voisin)
    return ordre

Complexité : chaque sommet est enfilé/défilé au plus une fois (O(n)), et chaque arête est examinée au plus deux fois, une depuis chaque extrémité (O(m)) — complexité totale O(n + m).

